-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/weather/src/
-- -- edit those files, not this one.
local kit = (function()
-- Shared UI + storage toolkit for the XT Weather mini app on the XTOS Licorice host.
-- tools/gamekit/bundle.py pastes this whole block in front of the app's entry script, because the
-- device host runs each app as one self-contained Lua state with no package loader.

local kit = {}

kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end

function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #tostring(s) * 11
end

function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end

function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end

function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end

function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end

function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, BOX_W, ROW_H, GAP = 20, kit.W - 40, 56, 10
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function modal_layout(m)
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.draw_modal(gg)
  local lines, btns, y, h = modal_layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = modal_layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['wx'] = function()
-- WX: weather data shaping and ink glyphs for XT Weather on the XTOS Licorice host.
-- The host runs one self-contained script per app, so this module travels inside index.lua
-- (inlined by tools/gamekit/bundle.py) and is reachable as require('wx').

local X = {}

-- Interpret a WMO weather code (as delivered by Open-Meteo) -> glyph kind + human label.
function X.kind(code)
  local n = tonumber(code) or 0
  local kind, label
  if n == 0 then kind, label = 'sun', 'Clear sky'
  elseif n == 1 then kind, label = 'sun', 'Mostly clear'
  elseif n == 2 then kind, label = 'partly', 'Partly cloudy'
  elseif n == 3 then kind, label = 'cloud', 'Overcast'
  elseif n == 45 or n == 48 then kind, label = 'fog', 'Fog'
  elseif n >= 51 and n <= 57 then kind, label = 'drizzle', 'Drizzle'
  elseif n >= 61 and n <= 67 then kind, label = 'rain', n >= 65 and 'Heavy rain' or 'Rain'
  elseif n >= 71 and n <= 77 then kind, label = 'snow', 'Snow'
  elseif n >= 80 and n <= 82 then kind, label = 'shower', 'Rain showers'
  elseif n == 85 or n == 86 then kind, label = 'snow', 'Snow showers'
  elseif n >= 95 then kind, label = 'storm', 'Thunderstorm'
  else kind, label = 'cloud', 'Cloudy' end
  return kind, label
end

-- Open-Meteo forecast endpoint (free, no key needed).
function X.forecast_url(lat, lon, unit)
  local q = {
    latitude = tostring(lat), longitude = tostring(lon),
    current = 'temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m',
    hourly = 'temperature_2m,precipitation_probability,weather_code',
    daily = 'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max',
    forecast_days = '7', timezone = 'auto', wind_speed_unit = 'kmh'
  }
  if unit == 'F' then q.temperature_unit = 'fahrenheit' end
  local parts = {}
  for k, v in pairs(q) do parts[#parts + 1] = k .. '=' .. v end
  return 'https://api.open-meteo.com/v1/forecast?' .. table.concat(parts, '&')
end

local function rnd(x) return x and math.floor(x + 0.5) or nil end

-- Open-Meteo JSON -> the "key=value" cache text stored between launches.
function X.cache_text(d, place, unit, now)
  local c = d.current or {}
  local out = {
    'place=' .. tostring(place), 'unit=' .. tostring(unit), 'updated=' .. tostring(now),
    'now_t=' .. (rnd(c.temperature_2m) or ''), 'now_feel=' .. (rnd(c.apparent_temperature) or ''),
    'now_code=' .. tostring(c.weather_code or 0), 'now_hum=' .. (rnd(c.relative_humidity_2m) or ''),
    'now_wind=' .. (rnd(c.wind_speed_10m) or '')
  }
  local h = d.hourly or {}
  local times = h.time or {}
  local first = 1
  local cur = tostring(c.time or ''):sub(1, 13)
  for i, t in ipairs(times) do
    if tostring(t):sub(1, 13) >= cur then
      first = i
      break
    end
  end
  for k = 0, 11 do
    local i = first + k
    if times[i] then
      out[#out + 1] = 'h' .. k .. '=' .. tostring(times[i]):sub(12, 16) .. ';' .. (rnd((h.temperature_2m or {})[i]) or '') .. ';' ..
        tostring((h.precipitation_probability or {})[i] or '') .. ';' .. tostring((h.weather_code or {})[i] or 0)
    end
  end
  local dd = d.daily or {}
  for i, t in ipairs(dd.time or {}) do
    out[#out + 1] = 'd' .. (i - 1) .. '=' .. tostring(t) .. ';' .. tostring((dd.weather_code or {})[i] or 0) .. ';' ..
      (rnd((dd.temperature_2m_min or {})[i]) or '') .. ';' .. (rnd((dd.temperature_2m_max or {})[i]) or '') .. ';' ..
      tostring((dd.precipitation_probability_max or {})[i] or '')
  end
  return table.concat(out, '\n')
end

function X.parse_cache(text)
  if not text then return nil end
  local t = {}
  for k, v in text:gmatch('([%w_]+)=([^\n]*)') do t[k] = v end
  if not t.place then return nil end
  local f = {
    place = t.place, unit = t.unit or 'C', updated = tonumber(t.updated),
    now_t = tonumber(t.now_t), now_feel = tonumber(t.now_feel), now_code = tonumber(t.now_code) or 0,
    now_hum = tonumber(t.now_hum), now_wind = tonumber(t.now_wind), hours = {}, days = {}
  }
  for k = 0, 11 do
    local v = t['h' .. k]
    if v then
      local tm, temp, rain, code = v:match('^([^;]*);([^;]*);([^;]*);([^;]*)$')
      if tm then f.hours[#f.hours + 1] = { time = tm, temp = tonumber(temp), rain = tonumber(rain), code = tonumber(code) or 0 } end
    end
  end
  for k = 0, 6 do
    local v = t['d' .. k]
    if v then
      local date, code, lo, hi, rain = v:match('^([^;]*);([^;]*);([^;]*);([^;]*);([^;]*)$')
      if date then f.days[#f.days + 1] = { date = date, code = tonumber(code) or 0, lo = tonumber(lo), hi = tonumber(hi), rain = tonumber(rain) } end
    end
  end
  return f
end

-- Weekday for a "YYYY-MM-DD" date (Zeller's congruence, 0 = Saturday).
local DAYS = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' }
function X.weekday(date)
  local y, m, d = date:match('^(%d+)-(%d+)-(%d+)')
  y, m, d = tonumber(y), tonumber(m), tonumber(d)
  if not y then return '' end
  if m < 3 then y, m = y - 1, m + 12 end
  local k = (d + (13 * (m + 1)) // 5 + y + y // 4 - y // 100 + y // 400) % 7
  return DAYS[(k + 6) % 7 + 1]
end

------------------------------------------------------------------ drawing

local function circle(gg, x, y, rad) pcall(function() gg:circle(x, y, rad) end) end

-- Weather glyph in a square of size s, top-left corner (x, y).
function X.icon(gg, kind, x, y, s)
  local function cloud(cx, cy, w)
    local h = w * 0.55
    local pts = {}
    local shape = { 0.1, 1, 0.9, 1, 1, 0.75, 0.88, 0.45, 0.68, 0.42, 0.6, 0.1, 0.35, 0.05, 0.22, 0.35, 0.05, 0.5, 0, 0.8, 0.1, 1 }
    for i = 1, #shape, 2 do
      pts[#pts + 1] = math.floor(cx + shape[i] * w)
      pts[#pts + 1] = math.floor(cy + shape[i + 1] * h)
    end
    gg:polyline(pts)
  end
  if kind == 'sun' then
    local cx, cy, rad = x + s // 2, y + s // 2, s // 5
    circle(gg, cx, cy, rad)
    circle(gg, cx, cy, rad - 1)
    for k = 0, 7 do
      local a = k * math.pi / 4
      gg:line(math.floor(cx + math.cos(a) * rad * 1.5), math.floor(cy + math.sin(a) * rad * 1.5),
        math.floor(cx + math.cos(a) * rad * 2.2), math.floor(cy + math.sin(a) * rad * 2.2))
    end
  elseif kind == 'partly' then
    local cx, cy, rad = x + s * 0.35, y + s * 0.3, s // 7
    circle(gg, math.floor(cx), math.floor(cy), rad)
    for k = 0, 4 do
      local a = math.pi * (0.75 + k * 0.25)
      gg:line(math.floor(cx + math.cos(a) * rad * 1.5), math.floor(cy + math.sin(a) * rad * 1.5),
        math.floor(cx + math.cos(a) * rad * 2.2), math.floor(cy + math.sin(a) * rad * 2.2))
    end
    cloud(x + s * 0.2, y + s * 0.35, s * 0.75)
  elseif kind == 'fog' then
    for k = 0, 3 do gg:line(x + s // 8 + (k % 2) * 6, y + s // 3 + k * s // 8, x + s - s // 8 - (k % 2) * 6, y + s // 3 + k * s // 8) end
  else
    cloud(x + s * 0.08, y + s * 0.12, s * 0.84)
    local by = math.floor(y + s * 0.72)
    if kind == 'rain' or kind == 'drizzle' or kind == 'shower' then
      for k = 0, 2 do local lx = math.floor(x + s * (0.3 + k * 0.2)); gg:line(lx, by, lx - 5, by + s // 5) end
    elseif kind == 'snow' then
      for k = 0, 2 do
        local lx = math.floor(x + s * (0.3 + k * 0.2))
        gg:line(lx - 4, by + 6, lx + 4, by + 6)
        gg:line(lx, by + 2, lx, by + 10)
      end
    elseif kind == 'storm' then
      local lx = math.floor(x + s * 0.5)
      gg:polyline({ lx + 4, by - 2, lx - 6, by + s // 8, lx + 4, by + s // 8, lx - 6, by + s // 4 })
    end
  end
end

-- Seven-segment rendering of a (possibly signed) integer string: digit height h, thickness t.
local SEG = { ['0'] = 'abcdef', ['1'] = 'bc', ['2'] = 'abged', ['3'] = 'abgcd', ['4'] = 'fgbc', ['5'] = 'afgcd',
             ['6'] = 'afgedc', ['7'] = 'abc', ['8'] = 'abcdefg', ['9'] = 'abcdfg', ['-'] = 'g' }
function X.big_number(gg, s, x, y, h)
  local w, t = h // 2, math.max(4, h // 10)
  local half = h // 2
  for ch in tostring(s):gmatch('.') do
    local seg = SEG[ch]
    if seg then
      for sg in seg:gmatch('.') do
        if sg == 'a' then gg:rect(x, y, w, t, { fill = true })
        elseif sg == 'b' then gg:rect(x + w - t, y, t, half, { fill = true })
        elseif sg == 'c' then gg:rect(x + w - t, y + half, t, h - half, { fill = true })
        elseif sg == 'd' then gg:rect(x, y + h - t, w, t, { fill = true })
        elseif sg == 'e' then gg:rect(x, y + half, t, h - half, { fill = true })
        elseif sg == 'f' then gg:rect(x, y, t, half, { fill = true })
        elseif sg == 'g' then gg:rect(x, y + half - t // 2, w, t, { fill = true }) end
      end
      x = x + w + t * 2
    end
  end
  return x
end
function X.big_width(s, h)
  local w, t = h // 2, math.max(4, h // 10)
  local n = 0
  for ch in tostring(s):gmatch('.') do if SEG[ch] then n = n + 1 end end
  return n * (w + t * 2)
end

return X
end

-- XT Weather: liquid-glass style forecast glance for the Xteink X4 Pro on XTOS Licorice.
-- Originally forked from touch-licorice-apps by Omer Faruk Inel; enhanced with Liquid Glass UI,
-- OTA updates, options menu, and expanded forecasts.
--
-- Layout: portrait (480x800) and landscape (800x480) are handled by the same state machine.
-- Data: Open-Meteo (free, no key) -> key=value cache file -> on-screen glance.

local X = require('wx')
local STALE_S = 30 * 60
local UA = 'XT Weather/1.4.1.1 (https://github.com/Valblasp/XT-Weather)'

local APP_VERSION = '1.4.1.1'
local UPDATE_URL = 'https://raw.githubusercontent.com/Valblasp/XT-Weather/xt-weather/version.json'
local update_info = nil

local cfg = { name = nil, lat = nil, lon = nil, unit = 'C' }
local fc = nil                  -- parsed forecast cache (X.parse_cache)
local screen = 'main'           -- main | places
local places = {}
local status, busy_label, ERR = nil, nil, nil

local function layout(gg)
  local w, h = kit.W or 480, kit.H or 800
  if gg and gg.size then
    local ok, sw, sh = pcall(function() return gg:size() end)
    if ok and type(sw) == 'number' and type(sh) == 'number' and sw > 0 and sh > 0 then
      w, h = sw, sh
    end
  end
  local is_land = (w > h)
  local bar_h = is_land and 50 or 66
  local bar_y = h - bar_h - 12
  return { w = w, h = h, is_land = is_land, bar_y = bar_y, bar_h = bar_h }
end

local L = layout()

local function now_sec()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if ok and type(t) == 'table' and tonumber(t.epoch_sec) then return math.floor(tonumber(t.epoch_sec)) end
  return 0
end

local function hhmm(epoch)
  if not epoch then return '' end
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not ok or type(t) ~= 'table' or not tonumber(t.hour) then return '' end
  local wall = tonumber(t.hour) * 3600 + (tonumber(t.minute) or 0) * 60 - (now_sec() - tonumber(epoch))
  wall = wall % 86400
  return string.format('%02d:%02d', wall // 3600, (wall % 3600) // 60)
end

------------------------------------------------------------------ storage

local function save_cfg()
  kit.write('settings.txt', 'name=' .. (cfg.name or '') .. '\nlat=' .. (cfg.lat or '') .. '\nlon=' .. (cfg.lon or '') ..
    '\nunit=' .. cfg.unit)
end

local function load_cfg()
  local t = kit.kv(kit.read('settings.txt'))
  cfg.name = (t.name and t.name ~= '') and t.name or nil
  cfg.lat, cfg.lon = tonumber(t.lat), tonumber(t.lon)
  cfg.unit = t.unit == 'F' and 'F' or 'C'
  fc = X.parse_cache(kit.read('forecast.txt'))
end

------------------------------------------------------------------ network

local function keep_wifi() pcall(function() ctx.net:keep_wifi(5 * 60 * 1000) end) end

local pending = nil
local function get(url, label, on_done)
  if pending then return end
  keep_wifi()
  busy_label, pending = label, { since = kit.now_ms() }
  local job = pending
  local ok, err = pcall(function()
    ctx.net:request({ url = url, method = 'GET', headers = { ['User-Agent'] = UA }, timeout_ms = 30000 }, function(c, resp)
      if pending ~= job then return end
      pending, busy_label = nil, nil
      local okh, e = pcall(function()
        if type(resp) ~= 'table' or type(resp.body) ~= 'string' then on_done(nil, 'no answer'); return end
        local code = tonumber(resp.status) or tonumber(resp.code)
        if code and code >= 400 then on_done(nil, 'HTTP ' .. code); return end
        local okj, data = pcall(function() return ctx.json:decode(resp.body) end)
        on_done(okj and type(data) == 'table' and data or nil, nil, resp.body)
      end)
      if not okh then status = 'Error: ' .. kit.short(tostring(e), 40) end
      kit.refresh()
    end)
  end)
  if not ok then pending, busy_label, status = nil, nil, 'Could not ask: ' .. kit.short(tostring(err), 30) end
end

local download_update  -- defined below; used by the update prompt

local function check_update(announce)
  get(UPDATE_URL, 'Checking update...', function(d, err, raw)
    if not d or type(d) ~= 'table' then
      if announce then status = 'Update check failed: ' .. tostring(err or 'no answer') end
      return
    end
    local remote_ver = tostring(d.version or '')
    if remote_ver ~= '' and remote_ver ~= APP_VERSION then
      local is_land = L and L.is_land
      local file_url = is_land and d.download_url_land or d.download_url
      local file_name = is_land and (d.filename_land or 'xtweatherland.xtapp') or (d.filename or 'xtweather.xtapp')
      local known = update_info ~= nil and update_info.version == remote_ver
      update_info = {
        version = remote_ver,
        url = file_url,
        filename = file_name,
        notes = tostring(d.notes or '')
      }
      status = 'New update v' .. remote_ver .. '! Tap Update'
      if not known then
        kit.show({
          title = 'Update v' .. remote_ver .. ' available',
          lines = { 'Download it now? The file is saved to App Files.', 'It is not installed automatically.' },
          cancel = function() kit.close() end,
          rows = {
            { { 'Download', function() kit.close(); download_update() end, true } },
            { { 'Later', function() kit.close() end, true } }
          }
        })
      end
    else
      update_info = nil
      if announce then status = 'Up to date (v' .. APP_VERSION .. ')' end
    end
  end)
end

local function refresh_forecast()
  if not cfg.lat then status = 'Choose a place first.'; return end
  get(X.forecast_url(cfg.lat, cfg.lon, cfg.unit), 'Getting the forecast...', function(d, err)
    if not d then status = 'Forecast failed: ' .. tostring(err); return end
    local text = X.cache_text(d, cfg.name, cfg.unit, now_sec())
    kit.write('forecast.txt', text)
    fc = X.parse_cache(text)
    status = nil
    check_update()   -- after a fresh forecast, also look for a new app version
  end)
end

download_update = function()
  if not update_info or not update_info.url then return end
  local target_url = update_info.url
  local fname = update_info.filename
  busy_label = 'Downloading update...'
  status = 'Downloading v' .. update_info.version .. '...'
  kit.refresh()

  get(target_url, 'Downloading update...', function(d, err, raw_body)
    if not raw_body or #raw_body < 1000 then
      status = 'Download failed: ' .. tostring(err or 'empty')
      return
    end
    local okw = pcall(function()
      if ctx.files and ctx.files.write then
        ctx.files:write(fname, raw_body)
      else
        kit.write(fname, raw_body)
      end
    end)
    if okw then
      busy_label = nil
      status = nil
      kit.show({
        title = 'Update downloaded',
        lines = { fname .. ' saved to App Files.', 'Open All Files, tap it, then Install.' },
        cancel = function() kit.close() end,
        rows = { { { 'OK', function() kit.close() end, true } } }
      })
    else
      status = 'Could not save file.'
    end
  end)
end

local function find_place(q)
  get('https://geocoding-api.open-meteo.com/v1/search?count=8&language=en&format=json&name=' ..
      q:gsub('[^A-Za-z0-9%-%._~]', function(c) return string.format('%%%02X', c:byte()) end),
      'Looking for ' .. kit.short(q, 20) .. '...', function(d, err)
    if not d then status = 'Search failed: ' .. tostring(err); return end
    places = {}
    for _k, p in ipairs(d.results or {}) do
      local where = {}
      if p.admin1 then where[#where + 1] = tostring(p.admin1) end
      if p.country then where[#where + 1] = tostring(p.country) end
      places[#places + 1] = { name = tostring(p.name), lat = tonumber(p.latitude), lon = tonumber(p.longitude),
                              where = table.concat(where, ', ') }
    end
    screen, status = 'places', (#places == 0 and 'No place by that name.' or nil)
  end)
end

local function ask_place()
  ctx.input:text({ title = 'Place (city or town)', text = '' }, function(c, s)
    if s and s:match('%S') then find_place(s) end
    kit.refresh()
  end)
end

local function open_menu()
  local unit_label = cfg.unit == 'C' and 'Switch to °F' or 'Switch to °C'
  kit.show({
    title = 'Menu',
    lines = { 'Place: ' .. (cfg.name or 'not set'), 'Version ' .. APP_VERSION },
    cancel = function() kit.close() end,
    rows = {
      { { 'Place', function() kit.close(); ask_place() end, true } },
      { { unit_label, function()
          kit.close()
          cfg.unit = cfg.unit == 'C' and 'F' or 'C'
          save_cfg()
          refresh_forecast()
        end, true } },
      { { 'Check updates', function() kit.close(); check_update(true) end, true } },
      { { 'Close', function() kit.close() end, true } }
    }
  })
end

------------------------------------------------------------------ drawing

local function deg(v) return v and (tostring(v) .. '°') or '-' end

local function draw_glass_bar(gg)
  gg:rect(12, L.bar_y, L.w - 24, L.bar_h, { line_width = 2 })
  gg:rect(14, L.bar_y + 2, L.w - 28, L.bar_h - 4, { line_width = 1 })
end

local function draw_button(gg, x, y, w, h, label)
  gg:rect(x, y, w, h, { line_width = 2 })
  local f = kit.font('medium')
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h('medium')) / 2), s, { font = f })
end

local function draw_main_portrait(gg)
  local W = L.w
  -- Clean header: city (left) + updated time (right)
  local place_str = kit.short(fc.place, 22)
  local upd_str = 'updated ' .. hhmm(fc.updated) .. (now_sec() - (fc.updated or 0) > STALE_S and ' (old)' or '')
  gg:text(16, 10, place_str, { font = kit.font('large') })
  gg:text(17, 10, place_str, { font = kit.font('large') })
  gg:text(W - kit.width(kit.font('small'), upd_str) - 16, 18, upd_str, { font = kit.font('small') })
  gg:line(0, 46, W, 46, { line_width = 1 })

  local kind, label = X.kind(fc.now_code)
  gg:text(16, 56, label, { font = kit.font('large') })

  -- big temperature + icon
  local temp = fc.now_t and tostring(fc.now_t) or '-'
  local bx = X.big_number(gg, temp, 20, 84, 110)
  gg:text(bx + 4, 84, '°' .. fc.unit, { font = kit.font('large') })
  X.icon(gg, kind, W - 136, 68, 114)

  -- single clean metrics line: feels like, humidity, wind
  local metrics_str = 'Feels ' .. deg(fc.now_feel) .. '   Humidity ' .. (fc.now_hum or '-') .. '%   Wind ' .. (fc.now_wind or '-') .. ' km/h'
  gg:text(16, 208, metrics_str, { font = kit.font('small') })
  gg:line(0, 234, W, 234, { line_width = 1 })

  -- Hourly forecast strip
  gg:text(16, 244, 'Hourly', { font = kit.font('medium') })
  local col = W // 6
  for k = 1, 6 do
    local h = fc.hours[(k - 1) * 2 + 1]
    if h then
      local cx = (k - 1) * col
      gg:text(cx + 8, 268, h.time, { font = kit.font('small') })
      X.icon(gg, X.kind(h.code), cx + 12, 290, 40)
      gg:text(cx + 10, 336, deg(h.temp), { font = kit.font('medium') })
      gg:text(cx + 10, 362, (h.rain or 0) .. '%', { font = kit.font('small') })
    end
  end
  gg:line(0, 388, W, 388, { line_width = 1 })

  -- 5-Day Outlook
  gg:text(16, 398, '5-Day Outlook', { font = kit.font('medium') })
  for k, d in ipairs(fc.days) do
    if k > 5 then break end
    local y = 422 + (k - 1) * 52
    gg:text(16, y + 14, k == 1 and 'Today' or X.weekday(d.date), { font = kit.font('medium') })
    X.icon(gg, X.kind(d.code), 110, y + 4, 42)
    gg:text(175, y + 14, deg(d.lo) .. ' / ' .. deg(d.hi), { font = kit.font('medium') })
    gg:text(310, y + 16, 'rain ' .. (d.rain or 0) .. '%', { font = kit.font('small') })
    if k < 5 then gg:line(16, y + 52, W - 16, y + 52, { line_width = 1 }) end
  end
end

local function draw_main_landscape(gg)
  local W = L.w
  -- Clean header
  local place_str = kit.short(fc.place, 26)
  local upd_str = 'updated ' .. hhmm(fc.updated) .. (now_sec() - (fc.updated or 0) > STALE_S and ' (old)' or '')
  gg:text(16, 10, place_str, { font = kit.font('large') })
  gg:text(17, 10, place_str, { font = kit.font('large') })
  gg:text(W - kit.width(kit.font('small'), upd_str) - 16, 18, upd_str, { font = kit.font('small') })
  gg:line(0, 44, W, 44, { line_width = 1 })

  local kind, label = X.kind(fc.now_code)
  gg:text(20, 54, label, { font = kit.font('large') })
  local temp = fc.now_t and tostring(fc.now_t) or '-'
  local bx = X.big_number(gg, temp, 20, 78, 72)
  gg:text(bx + 4, 78, '°' .. fc.unit, { font = kit.font('large') })
  X.icon(gg, kind, 260, 56, 84)

  -- single line metrics in left panel
  local metrics_str = 'Feels ' .. deg(fc.now_feel) .. '   Hum ' .. (fc.now_hum or '-') .. '%   Wind ' .. (fc.now_wind or '-') .. ' km/h'
  gg:text(20, 168, metrics_str, { font = kit.font('small') })

  -- Divider between current and daily
  gg:line(375, 44, 375, 206, { line_width = 1 })
  gg:line(0, 206, W, 206, { line_width = 1 })

  for k, d in ipairs(fc.days) do
    if k <= 4 then
      local y = 48 + (k - 1) * 38
      gg:text(390, y + 6, k == 1 and 'Today' or X.weekday(d.date), { font = kit.font('medium') })
      X.icon(gg, X.kind(d.code), 485, y, 32)
      gg:text(535, y + 6, deg(d.lo) .. ' / ' .. deg(d.hi), { font = kit.font('medium') })
      gg:text(690, y + 8, 'rain ' .. (d.rain or 0) .. '%', { font = kit.font('small') })
      if k < 4 then gg:line(390, y + 38, W - 16, y + 38, { line_width = 1 }) end
    end
  end

  local slots = 8
  local col = W // slots
  gg:text(16, 214, 'Hourly', { font = kit.font('medium') })
  for k = 1, slots do
    local h = fc.hours[k]
    if h then
      local cx = (k - 1) * col
      gg:text(cx + 18, 236, h.time, { font = kit.font('small') })
      X.icon(gg, X.kind(h.code), cx + 22, 256, 34)
      gg:text(cx + 20, 296, deg(h.temp), { font = kit.font('medium') })
      gg:text(cx + 20, 318, (h.rain or 0) .. '%', { font = kit.font('small') })
    end
  end
  gg:line(0, 342, W, 342, { line_width = 1 })
end

local function draw_main(gg)
  if not fc then
    gg:text(16, 16, 'XT Weather', { font = kit.font('large') })
    gg:text(16, L.is_land and 80 or 140, cfg.lat and 'Tap Refresh for the forecast.' or 'Tap Place to choose where.', { font = kit.font('medium') })
    return
  end
  if L.is_land then
    draw_main_landscape(gg)
  else
    draw_main_portrait(gg)
  end
end

local function draw_places(gg)
  local W = L.w
  gg:text(16, 16, 'Choose the place', { font = kit.font('large') })
  if not L.is_land then
    gg:line(0, 84, W, 84)
    for k, p in ipairs(places) do
      local y = 96 + (k - 1) * 76
      gg:text(20, y + 6, kit.short(p.name, 30), { font = kit.font('medium') })
      gg:text(20, y + 38, kit.short(p.where, 46), { font = kit.font('small') })
      gg:line(16, y + 70, W - 16, y + 70)
    end
  else
    gg:line(0, 46, W, 46)
    gg:line(395, 46, 395, L.bar_y - 8)
    for k, p in ipairs(places) do
      if k <= 8 then
        local col_idx = (k <= 4) and 0 or 1
        local row_idx = (k <= 4) and (k - 1) or (k - 5)
        local bx = (col_idx == 0) and 20 or 415
        local lx1 = (col_idx == 0) and 16 or 410
        local lx2 = (col_idx == 0) and 380 or (W - 16)
        local y = 52 + row_idx * 76
        gg:text(bx, y + 6, kit.short(p.name, 26), { font = kit.font('medium') })
        gg:text(bx, y + 38, kit.short(p.where, 38), { font = kit.font('small') })
        gg:line(lx1, y + 70, lx2, y + 70)
      end
    end
  end
end

local function buttons()
  if screen == 'places' then return { 'Back', 'Search again' } end
  if update_info then return { 'Update', 'Refresh', 'Menu' } end
  return { 'Refresh', 'Menu' }
end

local function button_rect(k, n)
  local bw = math.floor((L.w - 24 - (n - 1) * 8) / n)
  return 12 + (k - 1) * (bw + 8), L.bar_y, bw, L.bar_h
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    L = layout(gg)
    gg:clear(0)
    if kit.modal() then kit.draw_modal(gg); return end
    if screen == 'places' then draw_places(gg) else draw_main(gg) end
    local line = busy_label or status or ERR
    if line then
      local ly = L.bar_y - (L.is_land and 24 or 30)
      gg:text(12, ly, kit.short(tostring(line), L.is_land and 80 or 48), { font = kit.font('small') })
    end
    local bs = buttons()
    draw_glass_bar(gg)
    for k, b in ipairs(bs) do
      local x, y, bw, bh = button_rect(k, #bs)
      draw_button(gg, x, y, bw, bh, b)
    end
  end)
  if not ok then pcall(function() gg:text(8, L.h - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  local bs = buttons()
  for k, b in ipairs(bs) do
    local bx, by, bw, bh = button_rect(k, #bs)
    if x >= bx and x < bx + bw and y >= by and y < by + bh then
      status = nil
      if b == 'Update' then download_update()
      elseif b == 'Refresh' then refresh_forecast()
      elseif b == 'Menu' then open_menu()
      elseif b == 'Place' or b == 'Search again' then ask_place()
      elseif b == 'Back' then screen = 'main'
      else
        cfg.unit = cfg.unit == 'C' and 'F' or 'C'
        save_cfg()
        refresh_forecast()
      end
      return
    end
  end
  if screen == 'places' then
    local p = nil
    if not L.is_land and y >= 96 then
      p = places[(y - 96) // 76 + 1]
    elseif L.is_land and y >= 52 and y < L.bar_y - 8 then
      local row = (y - 52) // 76
      if row >= 0 and row < 4 then
        local idx = (x < 395) and (row + 1) or (row + 5)
        p = places[idx]
      end
    end
    if p then
      cfg.name, cfg.lat, cfg.lon = p.name, p.lat, p.lon
      save_cfg()
      screen = 'main'
      refresh_forecast()
    end
  end
end

local function try_quit()
  pcall(function()
    if ctx.quit then ctx:quit()
    elseif ctx.system and ctx.system.quit then ctx.system:quit()
    elseif ctx.system and ctx.system.exit then ctx.system:exit()
    end
  end)
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if ev.key == 'home' or ev.key == 'menu' then
        try_quit()
        return false
      elseif kit.modal() then
        if ev.key == 'back' and kit.modal().cancel then kit.modal().cancel() end
      elseif ev.key == 'back' and screen == 'places' then screen = 'main'
      elseif ev.key == 'back' then
        try_quit()
        return false
      end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(load_cfg)
  if not ok then ERR = tostring(e) end
  if cfg.lat then refresh_forecast() else check_update() end
end

function on_leave() pcall(function() ctx.net:keep_wifi(1) end) end

if rawget(_G, '__TEST') then
  __TEST.api = { X = X, fc = function() return fc end, cfg = cfg, screen = function() return screen end,
                 places = function() return places end, status = function() return status end }
end
